package com.bancatest.reconciliation.domain.model.vo;

import java.util.UUID;

/**
 * The internal identity of a reconciliation.
 *
 * <p>Carries a UUIDv7, generated by the application rather than by the database, so that
 * {@code Reconciliation.start(...)} can return a complete aggregate before anything is
 * persisted. UUIDv7 is time-ordered, which keeps the primary-key index from fragmenting the
 * way random UUIDv4 keys do.
 *
 * <p>The domain does not know how the value is produced: generation lives in infrastructure.
 */
public record ReconciliationId(UUID value) {

    public ReconciliationId {
        if (value == null) {
            throw new IllegalArgumentException("ReconciliationId must not be null");
        }
    }

    public static ReconciliationId of(UUID value) {
        return new ReconciliationId(value);
    }

    public static ReconciliationId fromString(String value) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException("ReconciliationId text must not be null or blank");
        }
        return new ReconciliationId(UUID.fromString(value));
    }

    @Override
    public String toString() {
        return value.toString();
    }
}
